tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-families-offer-arm-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e bench/variations/stage7-3c-families-offer-arm.json -e scripts/ringer/stage7/three_c_probe.py -e scripts/ringer/stage7/check_three_c_probe.py -e tests/test_3c_families_offer_arm.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_families_offer_arm.py tests/test_3c_no_close_arm.py tests/test_3c_item_facts_arm.py tests/test_3c_item_facts_capture.py tests/test_3c_kristin_place.py tests/test_3c_carried_start.py tests/test_3c_escape_result.py tests/test_3c_custody_result.py tests/test_3c_entry_package.py tests/test_3c_pump_need.py tests/test_canonical_event_delivery.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
rm -rf /tmp/fo-arm-dry; $PY scripts/ringer/stage7/three_c_probe.py --n 12 --mode play --start postc --arms item-facts,families-offer --kristin-place facility_escape --capture-item-facts --semantic on --dry-run --out /tmp/fo-arm-dry >/dev/null || exit 1
$PY scripts/ringer/stage7/check_three_c_probe.py /tmp/fo-arm-dry 12 --mode dry || exit 1
grep -q '"first_command": null' /tmp/fo-arm-dry/source.json || { echo "FAIL: dry plan carries a scripted first command"; exit 1; }
$PY -m ruff check scripts/ringer/stage7 tests/test_3c_families_offer_arm.py && $PY -m ruff format --check scripts/ringer/stage7 tests/test_3c_families_offer_arm.py || exit 1
git add -A -- scripts tests bench/variations && git diff --cached -- scripts tests bench/variations > /home/bcorfman/dev/ringer-work/3c-families-offer-arm.patch && test -s /home/bcorfman/dev/ringer-work/3c-families-offer-arm.patch && echo "patch exported"
